import React from 'react';
import { About, Contact, Experience, Feedbacks, Hero, Navbar, Tech, Works } from "../../componentHome";
// import { About, Contact, Experience, Feedbacks, Hero, Navbar, Tech, Works, StarsCanvas } from "../../componentHome";
import './index.css';

export default function HomePage() {
  const isMobile = window.matchMedia("(max-width: 768px)").matches;
  return (
    <div className='relative z-0 bg-primary'>
        <div className='bg-hero-pattern bg-cover bg-no-repeat bg-center'>
          <Navbar />
          <Hero />
        </div>
        <About />
        {!isMobile && <Tech />}
        <Experience />
        <Works />
        <Feedbacks />
        <div className='relative z-0'>
          <Contact />
          {/* <StarsCanvas /> */}
        </div>
      </div>
  );
};