import i18n from 'i18next';
import { initReactI18next } from 'react-i18next';

import vnGlobal from '../locales/vn/global.json';
import enGlobal from '../locales/en/global.json';
import vnHome from '../locales/vn/home.json';
import enHome from '../locales/en/home.json';

const resources = {
  en: {
    global: enGlobal,
    home: enHome,
  },
  vn: {
    global: vnGlobal,
    home: vnHome,
  },
};

i18n
  .use(initReactI18next)
  .init({
    resources,
    lng: 'vn',
    fallbackLng: 'en',
    interpolation: {
      escapeValue: false,
    },
  });

export default i18n;