import React, { useRef, useState } from "react";
import ReCAPTCHA from "react-google-recaptcha";
import { motion } from "framer-motion";
import emailjs from "@emailjs/browser";

import { styles } from "../styles";
import { EarthCanvas } from "./canvas";
import { SectionWrapper } from "../hoc";
import { slideIn } from "../utils/motion";
import { useTranslation } from "react-i18next";

const Contact = () => {
  const formRef = useRef();
  const [form, setForm] = useState({
    name: "",
    email: "",
    message: "",
  });
  const { t } = useTranslation(['home']);
  const [loading, setLoading] = useState(false);
  const [recaptchaResult, setRecaptchaResult] = useState(null);
  const isMobile = window.matchMedia("(max-width: 768px)").matches;

  const handleChange = (e) => {
    const { target } = e;
    const { name, value } = target;

    setForm({
      ...form,
      [name]: value,
    });
  };

  const handleSubmit = (e) => {
    e.preventDefault();
    if (loading  || !recaptchaResult) {
      return;
    }
    setLoading(true);
    emailjs
      .send(
        process.env.REACT_APP_EMAILJS_SERVICE_ID,
        process.env.REACT_APP_EMAILJS_TEMPLATE_ID,
        {
          from_name: form.name,
          to_name: "Website portfolio",
          from_email: form.email,
          to_email: "trung@855100@gmail.com",
          message: form.message,
        },
        process.env.REACT_APP_EMAILJS_PUBLIC_KEY
      )
      .then(
        () => {
          setLoading(false);
          alert("Thank you. I will get back to you as soon as possible.");

          setForm({
            name: "",
            email: "",
            message: "",
          });
        },
        (error) => {
          setLoading(false);
          console.error(error);

          alert("Ahh, something went wrong. Please try again.");
        }
      );
  };

  return (
    <div
      className={`xl:mt-8 flex xl:flex-row flex-col-reverse gap-10 overflow-hidden`}
    >
      <motion.div
        variants={slideIn("left", "tween", 0.2, 1)}
        className='flex-[0.75] bg-black-100 p-8 rounded-2xl'
      >
        <h3 className={styles.sectionHeadText}>{t('contact.title',{ns : 'home'})}</h3>

        <form
          ref={formRef}
          onSubmit={handleSubmit}
          className='mt-5 flex flex-col gap-8'
        >
          <label className='flex flex-col'>
            <span className='text-white font-medium mb-4'>{t('contact.name',{ns : 'home'})}</span>
            <input
              type='text'
              name='name'
              value={form.name}
              required
              onChange={handleChange}
              placeholder={t('contact.name',{ns : 'home'})+" ?"}
              className='bg-tertiary py-4 px-6 placeholder:text-secondary text-white rounded-lg outline-none border-none font-medium'
            />
          </label>
          <label className='flex flex-col'>
            <span className='text-white font-medium mb-4'>{t('contact.email',{ns : 'home'})}</span>
            <input
              type='email'
              name='email'
              value={form.email}
              required
              onChange={handleChange}
              placeholder="example@gmail.com"
              className='bg-tertiary py-4 px-6 placeholder:text-secondary text-white rounded-lg outline-none border-none font-medium'
            />
          </label>
          <label className='flex flex-col'>
            <span className='text-white font-medium mb-4'>{t('contact.message',{ns : 'home'})}</span>
            <textarea
              rows={7}
              name='message'
              value={form.message}
              required
              onChange={handleChange}
              placeholder={t('contact.message',{ns : 'home'})+" ?"}
              className='bg-tertiary py-4 px-6 placeholder:text-secondary text-white rounded-lg outline-none border-none font-medium'
            />
          </label>
          <ReCAPTCHA
            sitekey={process.env.REACT_APP_YOUR_RECAPTCHA_SITE_KEY}
            onChange={(result) => setRecaptchaResult(result)}
          />
          <button
            type='submit'
            className='bg-tertiary py-3 px-8 rounded-xl outline-none w-fit text-white font-bold shadow-md shadow-primary'
          >
            {loading ? t('contact.submit',{ns : 'home'})+"..." : t('contact.submit',{ns : 'home'})}
          </button>
        </form>
      </motion.div>
      {!isMobile && <motion.div
        variants={slideIn("right", "tween", 0.2, 1)}
        className='xl:flex-1 xl:h-auto md:h-[550px] h-[350px]'
      >
        <EarthCanvas />
      </motion.div>}
      
    </div>
  );
};

export default SectionWrapper(Contact, "contact");
