import React, {  useRef, useState } from "react";
import { Tilt } from "react-tilt";
import { motion } from "framer-motion";
import { Trans, useTranslation } from "react-i18next";

import { styles } from "../styles";
import { SectionWrapper } from "../hoc";
import { projects } from "../constants";
import { textVariant, textVariantDes } from "../utils/motion";

const ProjectCard = ({
  index,
  name,
  description,
  tags,
  image,
  source_code_link,
  t,
}) => {
  return (
    <motion.div initial={{ opacity: 0, scale: 0.3 }} animate={{ opacity: 1, scale: 1 }} transition={{ duration: 0.5 }} className='sm:w-[calc(100%/3-1rem)] w-[100%] w-full'>
      <Tilt
        options={{
          max: 25,
          scale: 1,
          speed: 650,
        }}
        className='bg-tertiary p-2 w-full rounded-2xl'
      >
        <div className='relative w-full h-[230px]'>
          <img
            src={image}
            alt='project_image'
            className='w-full h-full object-cover rounded-2xl'
            loading="lazy"
          />
        </div>

        <div className='mt-5'>
          <h3 className='text-white font-bold text-[24px]'>{name}</h3>
          <p className='mt-2 text-secondary text-[14px]'>{t(description,{ns : 'home'})}</p>
          {(source_code_link !== '') && (<div onClick={() => window.open(source_code_link, "_blank")} className="mt-4 cursor-pointer inline-flex items-center justify-center px-5 py-2  text-base font-medium text-gray-500 rounded-lg bg-gray-50 hover:bg-gray-100 dark:text-gray-400 dark:bg-gray-800 dark:hover:bg-gray-700 dark:hover:text-white">
          {t('work.projects.visit_website',{ns : 'home'})}
            <svg className="w-3.5 h-3.5 ml-2" aria-hidden="true" xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 14 10">
                <path stroke="currentColor" strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M1 5h12m0 0L9 1m4 4L9 9"/>
            </svg>
          </div>
          )}
          {(source_code_link === '')&& (<div className="mt-4 cursor-block inline-flex items-center justify-center px-5 py-2  text-base font-medium text-yellow-500 rounded-lg bg-yellow-50 hover:text-yellow-900 hover:bg-yellow-100 dark:text-yellow-400 dark:bg-gray-800 dark:hover:bg-gray-700 dark:hover:text-white">
          {t('work.projects.local',{ns : 'home'})}
          </div>
          )}
        </div>

        <div className='mt-4 flex flex-wrap gap-2'>
          {tags.map((tag) => (
            <p
              key={`${name}-${tag.name}`}
              className={`text-[14px] ${tag.color}`}
            >
              #{tag.name}
            </p>
          ))}<p className={`text-[14px]`}>#...</p>
        </div>
      </Tilt>
    </motion.div>
  );
};

const Works = () => {
  const [typeWork, setTypeWork] = useState("all");
  const [visibleProjects, setVisibleProjects] = useState(6);
  const { t } = useTranslation(['home']);
  const filteredProjects = typeWork === "all" ? projects : projects.filter(project => project.type === typeWork);
  const projectRef = useRef(null);

  const handleLoadMore = () => {
    const showMore = visibleProjects + 6;
    setVisibleProjects(showMore);
  };

  const handleTypeWor = (e) => {
    setVisibleProjects(visibleProjects);
    setTypeWork(e.target.value);
  };

  const handleCloseLoadMore = () => {
    setVisibleProjects(6);
    scrollToProject();
  };

  const scrollToProject = () => {
    if (projectRef.current) {
      projectRef.current.scrollIntoView({ behavior: "smooth", block: "start" });
    }
  };
  return (
    <>
      <motion.div variants={textVariant()}>
        <p className={styles.sectionSubText}>{t('work.intro',{ns : 'home'})}</p>
        <h2 className={styles.sectionHeadText}>{t('work.overview',{ns : 'home'})}</h2>
      </motion.div>

      <div className='w-full flex'>
        <motion.p
          variants={textVariantDes()}
          className='mt-4 text-secondary text-[17px] max-w-3xl leading-[30px]'
        >
          <Trans i18nKey="work.des" ns="home"/>
        </motion.p>
      </div>
      <div className='mt-5 flex flex-wrap content-center gap-2'>
        <label htmlFor="type_project" className="flex-wrap content-center  w-[180px] block pt-2 leading-[26px] pb-2 text-sm font-medium dark:text-white"><span>{t('work.type_project',{ns : 'home'})} <sub>({filteredProjects.length})</sub></span></label>
        <select value={typeWork}  ref={projectRef} onChange={(e) => handleTypeWor(e)}
          id="type_project"
          className="border border-gray-300 text-sm rounded-lg focus:ring-blue-500 focus:border-blue-500 block w-[200px] p-2.5 dark:bg-gray-700 dark:border-gray-600 dark:placeholder-gray-400 dark:text-white dark:focus:ring-blue-500 dark:focus:border-blue-500"
        >
          <option value="all">{t('work.projects.select_all',{ns : 'home'})}</option>
          <option value="woocommerce">{t('work.projects.select_woo',{ns : 'home'})}</option>
          <option value="event">{t('work.projects.select_event',{ns : 'home'})}</option>
          <option value="job">{t('work.projects.select_job',{ns : 'home'})}</option>
          <option value="intro">{t('work.projects.select_intro',{ns : 'home'})}</option>
          <option value="bank">{t('work.projects.select_bank',{ns : 'home'})}</option>
        </select>
      </div>
      <label className="mt-6 mb-3 block pt-1 leading-[26px] text-sm font-medium text-secondary"><span><Trans i18nKey="work.show_project" values={{public: projects.length, hide: '30'}} ns="home"/></span></label>

      <div className='flex flex-wrap gap-4 content-center justify-center'>
        {filteredProjects.slice(0, visibleProjects).map((project, index) => (
          <ProjectCard key={`project-${index}`} index={index} t={t} {...project} />
        ))}
      </div>
      <div className='mt-5 flex flex-wrap content-center justify-center gap-2  mt-10'>
        {visibleProjects < filteredProjects.length && (
          <div className="relative w-[150px]  inline-flex items-center justify-center">
            <button onClick={handleLoadMore}  className="relative inline-flex items-center justify-center p-0.5 mb-2 mr-2 overflow-hidden text-sm font-medium rounded-lg group bg-gradient-to-br from-purple-600 to-blue-500 group-hover:from-purple-600 group-hover:to-blue-500 hover:text-white dark:text-white focus:ring-4 focus:outline-none focus:ring-blue-300 dark:focus:ring-blue-800">
              <span className="relative px-5 py-2.5 transition-all ease-in duration-75 bg-white dark:bg-gray-900 rounded-md group-hover:bg-opacity-0">
              {t('work.loadmore',{ns : 'home'})}
              </span>
            </button>
          </div>
        )}
        
        {(visibleProjects > 6) && (
          <div className="relative w-[130px]  inline-flex items-center justify-center">
            <button onClick={() => handleCloseLoadMore()}  className="relative inline-flex items-center justify-center p-0.5 mb-2 mr-2 overflow-hidden text-sm font-medium rounded-lg group bg-gradient-to-br from-purple-600 to-blue-500 group-hover:from-purple-600 group-hover:to-blue-500 hover:text-white dark:text-white focus:ring-4 focus:outline-none focus:ring-blue-300 dark:focus:ring-blue-800">
              <span className="relative px-5 py-2.5 transition-all ease-in duration-75 bg-white dark:bg-purple-900 rounded-md group-hover:bg-opacity-0">
              {t('work.close',{ns : 'home'})}
              </span>
            </button>
          </div>
        )}
      </div>
    </>
  );
};

export default SectionWrapper(Works, "work");
